MultiLanguageSpellData['ru'][401123] = {name = "Дикий вихрь клинков", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Нелтарион раз в 6 сек. в течение 30 сек. заставляет воина применить \" Дикий вихрь клинков \", в результате чего воин наносит 25 ед. физического урона игрокам и существам в радиусе 8 м раз в 1 сек. в течение 4 сек."}
MultiLanguageSpellData['ru'][401124] = {name = "Рьяная казнь", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Нелтарион извращает веру паладина, вынуждая его призывать молот света раз в 6 сек. в течение 30 сек. Молот освящает землю, нанося 10 ед. урона от светлой магии тем, кто стоит в этой области, и 50 ед. урона от светлой магии, когда молот приземляется через 5 сек."}
MultiLanguageSpellData['ru'][401125] = {name = "Порча", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Нелтарион вынуждает охотника призвать зараженных порчей зверей из стойл, и звери атакуют игроков.\n\n После смерти зверя охотника усиливает \" Освобожденная тьма \"."}
MultiLanguageSpellData['ru'][401126] = {name = "Порча", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Нелтарион играет на природном коварстве разбойника, вынуждая его раз в 10 сек. делать шаг сквозь тень к союзнику и метать кинжалы во все цели в радиусе 10 м, нанося 20 ед. физического урона. Кроме того, пораженные цели отравляет \" Дикий яд \"."}
MultiLanguageSpellData['ru'][401127] = {name = "Отчаянный крик", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Порча Нелтариона подвергает испытанию веру жреца, и тот исторгает \" Отчаянный крик \" раз в 6 сек. в течение 30 сек. Игроки и существа в радиусе 8 м получают 7 ед. урона от темной магии раз в 1 сек. и бегут в ужасе в течение 6 сек.\n\n За каждую пораженную цель жрец получает эффект \" Слово Тьмы: Измена \", который суммируется до 5 раз."}
MultiLanguageSpellData['ru'][401128] = {name = "Порча", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Нелтарион искажает силу рыцаря смерти, вынуждая его создавать области эффекта \" Дикий мор \", применять \"Хватку смерти\" к союзникам и притягивать их к себе раз в 10 сек. в течение 30 сек."}
MultiLanguageSpellData['ru'][401129] = {name = "Тотем элементаля Тьмы", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Нелтарион вынуждает шамана установить тотемы, призывающие враждебного элементаля Тьмы.\n\n После смерти элементаля шаман усиливается эффектом \" Освобожденная тьма \"."}
