MultiLanguageSpellData['ru'][401131] = {name = "Порча", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Нелтарион вынуждает чернокнижника призывать галлюцинации в виде прожорливых тварей Бездны, которые атакуют его в течение 25 сек.\n\n Если чернокнижник убивает одну из тварей, он усиливается эффектом \" Освобожденная тьма \"."}
