MultiLanguageSpellData['ru'][405524] = {name = "Hunter Beast Mastery 10.1 Class Set 2pc", additional_info = "[q]Увеличивает урон от \"Выстрела кобры\" и \"Команды \"Взять!\" на 15%."}
MultiLanguageSpellData['ru'][405525] = {name = "Hunter Beast Mastery 10.1 Class Set 4pc", additional_info = "[q]\"Выстрел кобры\", \"Команда \"Взять!\" и \"Залп\" сокращают время восстановления \"Звериного гнева\" на 2.0 сек."}
MultiLanguageSpellData['ru'][405526] = {name = "Hunter Marksmanship 10.1 Class Set 2pc", additional_info = "[q][ Выстрел химеры : \"Выстрел химеры\" / \"Чародейский выстрел\"] и \"Залп\" наносят на 10% больше урона и с вероятностью 8% дают эффект \"Убийственный удар\".\n(Вероятность срабатывания: 8%)"}
MultiLanguageSpellData['ru'][405527] = {name = "Hunter Marksmanship 10.1 Class Set 4pc", additional_info = "[q]\"Убийственный выстрел\" наносит на 15% больше урона и на 1.5 сек. сокращает время восстановления \"Прицельного выстрела\" и \"Быстрой стрельбы\"."}
MultiLanguageSpellData['ru'][405528] = {name = "Hunter Survival 10.1 Class Set 2pc", additional_info = "[q]\"Огнебомба\" наносит на 10% больше урона. Когда вы бросаете ее, урон от следующей \"Команды \"Взять!\" увеличивается на 40%."}
