MultiLanguageSpellData['ru'][405530] = {name = "Hunter Survival 10.1 Class Set 4pc", additional_info = "[q]За каждые 30 ед. израсходованной концентрации время восстановления \"Огнебомбы\" сокращается на 1.0 сек."}
MultiLanguageSpellData['ru'][405531] = {name = "Взрыв", additional_info = "Радиус действия: 40 м\nПрименение: 1.5 сек\n[q]Наносит цели урон от огня."}
MultiLanguageSpellData['ru'][405532] = {name = "Mage Arcane 10.1 Class Set 2pc", additional_info = "[q]\"Чародейский выброс\" увеличивает урон от заклинаний еще на 10% и длится на 3 сек. дольше."}
MultiLanguageSpellData['ru'][405533] = {name = "Mage Arcane 10.1 Class Set 4pc", additional_info = "[q]Когда действие \"Чародейского выброса\" завершается, ваш урон от заклинаний увеличивается на 1.0% за каждые 420000 ед. маны, затраченные вами на \"Чародейский выброс\" и израсходованные во время его действия. Эффект суммируется до 25 раз:раз и длится 18 сек. На это время скорость восполнения маны повышается на 50%."}
MultiLanguageSpellData['ru'][405534] = {name = "Mage Fire 10.1 Class Set 2pc", additional_info = "[q]\"Пламя феникса\" применяет \"Жгучие угли\" ко всем пораженным противникам, в результате чего они получают от вас на 6% больше урона в течение 14 сек."}
MultiLanguageSpellData['ru'][405535] = {name = "Mage Fire 10.1 Class Set 4pc", additional_info = "[q]Когда ваши заклинания прямого действия 25 раза:раз поразят противника под действием \"Жгучих углей\", следующие 2 применения:применений \"Пламени феникса\" нанесут на 100% больше урона и вернут 1 заряд."}
MultiLanguageSpellData['ru'][405536] = {name = "Mage Frost 10.1 Class Set 2pc", additional_info = "[q]\"Шквал\" и \"Ледяная стрела\" наносят на 20% больше урона. \"Шквал\" при попадании вызывает взрыв, наносящий 35% урона ближайшим противникам. Цели после 5-й получают меньше урона."}
MultiLanguageSpellData['ru'][405538] = {name = "Mage Frost 10.1 Class Set 4pc", additional_info = "[q]Когда \"Ледяное копье\" поражает замороженную цель, с вероятностью 10% срабатывает \"Заморозка мозгов\"."}
MultiLanguageSpellData['ru'][405539] = {name = "Monk Brewmaster 10.1 Class Set 2pc", additional_info = "[q]\"Нокаутирующий удар\" наносит на 20% больше урона. С вероятностью 10% эффекты \"Верткого задиры\" не сбросятся после успешного уклонения."}
MultiLanguageSpellData['ru'][405540] = {name = "Monk Brewmaster 10.1 Class Set 4pc", additional_info = "[q]\"Удар восходящего солнца\" дает один эффект \"Верткого задиры\". Когда вы уклоняетесь, урон и вероятность критического удара следующего \"Танцующего журавля\" или \"Удара восходящего солнца\" повышаются на 5%. Суммируется до 5 раз."}
MultiLanguageSpellData['ru'][405541] = {name = "Monk Mistweaver 10.1 Class Set 2pc", additional_info = "[q]\"Заживляющий туман\", \"Успокаивающий туман\" и \"Окутывающий туман\" восстанавливают на 12% больше здоровья."}
MultiLanguageSpellData['ru'][405542] = {name = "Monk Mistweaver 10.1 Class Set 4pc", additional_info = "[q]Когда вы пьете чай, исцеление от \"Оживить\" и \"Заживляющего тумана\" усиливается на 40% на 6 сек."}
MultiLanguageSpellData['ru'][405543] = {name = "Monk Windwalker 10.1 Class Set 2pc", additional_info = "[q]\"Удар восходящего солнца\" наносит на 5% больше урона и создает вспышку, наносящую ([83% of Attack Power]) ед. урона от пламени Тьмы всем противникам в радиусе 8 м."}
MultiLanguageSpellData['ru'][405544] = {name = "Monk Windwalker 10.1 Class Set 4pc", additional_info = "Срабатывает приблизительно 2 раз(а) в минуту\n[q]Ваши автоатаки ближнего боя могут с некоторой вероятностью натравить на вашего противника дух пламени Тьмы. Дух копирует ваши способности в течение 7.5 сек. с эффективностью 20%."}
MultiLanguageSpellData['ru'][405545] = {name = "Paladin Holy 10.1 Class Set 2pc", additional_info = "[q]Критические эффекты \"Шока небес\" восстанавливают на 80% больше здоровья и сокращают время восстановления \"Молота Света\" на 2 сек. или \"Божественной призмы\" на 1.0 сек."}
MultiLanguageSpellData['ru'][405546] = {name = "Paladin Holy 10.1 Class Set 4pc", additional_info = "[q]\"Молот Света\" срабатывает на 100% чаще и дает 1 ед. энергии Света раз в 4 сек. \"Божественная призма\" восстанавливает на 40% больше здоровья и дает 1 ед. энергии Света при применении к противнику и 3 ед. – при применении к союзнику."}
MultiLanguageSpellData['ru'][405547] = {name = "Paladin Protection 10.1 Class Set 2pc", additional_info = "[q]\"Щит мстителя\" поджигает цели \"Сердечным огнем\", нанося еще 20% периодического урона за 5 сек. \"Сердечный огонь\" восстанавливает вам здоровье в объеме 100% от своего урона."}
MultiLanguageSpellData['ru'][405548] = {name = "Paladin Protection 10.1 Class Set 4pc", additional_info = "[q]Критические удары \"Правосудия\" накладывают на цель \"Сердечный огонь\" и могут активировать \"Великого воина Света\"."}
MultiLanguageSpellData['ru'][405549] = {name = "Классовый комплект паладина 10.1 – воздаяние, 2 предмета", additional_info = "[q]\"Правосудие\" и \"Молот гнева\" наносят на 10% больше урона и на 15% больше критического урона. \"Молот гнева\" применяет к противникам эффект \"Правосудие\"."}
MultiLanguageSpellData['ru'][405550] = {name = "Классовый комплект паладина 10.1 – воздаяние, 4 предмета", additional_info = "[q]\"Правосудие\" увеличивает урон от способностей, расходующих силу Света, еще на 15%. \"Молот гнева\" теперь поражает еще 4 ближайших цели:ближайших целей, нанося им 20% основного урона."}
MultiLanguageSpellData['ru'][405551] = {name = "Priest Discipline 10.1 Class Set 2pc", additional_info = "[q][ Очищение зла : \"Очищение зла\" / \"Слово Тьмы: Боль\"] наносит на 25% больше урона. \"Слово силы: Сияние\" восполняет на 15% больше здоровья."}
