MultiLanguageSpellData['ru'][405824] = {name = "Заряженный удар сплеча", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Рашок бьет по земле усиленным пламенем Тьмы Джарууном, распределяя 4297555 ед. урона от пламени Тьмы между игроками в радиусе 10 м. Все игроки получают эффект \" Перегруженность \".[\n\n После удара Рашок накапливает до 50 ед. энергии. Количество энергии уменьшается с количеством пораженных игроков."}
