MultiLanguageSpellData['ru'][410230] = {name = "Пульсирующий плащ из спор", additional_info = "[q]Когда уровень здоровья выше 70%, повышает универсальность на 7 и восполняет 53 ед. здоровья раз в 5 сек.\n\n Когда уровень здоровья ниже 30%, споры-симбионты в ткани плаща оживают и на 10 сек. дают щит, поглощающий 1275 ед. урона. Срабатывает не чаще раза в 2 мин."}
