MultiLanguageSpellData['ru'][414590] = {name = "[q4]Кидатели копыт", additional_info = "Применение: 3.5 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nИстерзанный обрывок (35), Ториевый слиток (30), Золотой слиток (6), Большой опал (2), Арканитовый слиток (6), Синий сапфир (6)\nНаходка:\nНаксрамас\n\n[q4]Кидатели копыт\nСтановится персональным при надевании\nСтупни Латы\nБроня: 9\n+3 к [силе или интеллекту]+4 к выносливости\n[q2]+ 2 к критическому удару\n[q2]+ 3 к скорости\nПрочность: 80 / 80\nТребуется"}
