MultiLanguageSpellData['ru'][416687] = {name = "[q3]Священный страж", additional_info = "Применение: 3.5 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nСлиток истинного серебра (28), Сфера Праведности (5)\nНаходка:\nНекроситет\n\n[q3]Священный страж\nСтановится персональным при надевании\nЛевая рука Щит\nБроня: 42\n+2 к силе\n+6 к интеллекту\n+3 к выносливости\nПрочность: 100 / 100"}
MultiLanguageSpellData['ru'][416688] = {name = "[q2]Рассекатель лимфы", additional_info = "Применение: 3.5 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nАрканитовый слиток (2), Массивный шлифовальный камень (2), Огромный изумруд (6), Огромная ядовитая железа (10)\nНаходка:\nНекроситет\n\n[q2]Рассекатель лимфы\nСтановится персональным при надевании\nОдноручное Топор\nУрон: 3 - 7 Скорость 2.60\n(1.9 ед. урона в секунду)\nПрочность: 75 / 75\n[q2]Если на персонаже: 0 ед. урона от сил природы раз в 2 сек. в течение 20 сек."}
MultiLanguageSpellData['ru'][416689] = {name = "[q2]Ослоп Каменного черепа", additional_info = "Применение: 3.5 сек\nИнструменты: Тангенциальный вращатель , Шлицевой гироинструмент\nИнгредиенты:\nТангенциальный вращатель , Трещащий бронзовый механизм (5), Слиток истинного серебра (6), Субстанция нежити (6), Ториевое устройство (3)\nНаходка:\nНекроситет\n\n[q2]Ослоп Каменного черепа\nСтановится персональным при надевании\nОдноручное Дробящее\nУрон: 2 - 3 Скорость 2.60\n(1.0 ед. урона в секунду)\n+10 к интеллекту\n+3 к выносливости\n[q2]+ 1 к универсальности\nПрочность: 75 / 75"}
MultiLanguageSpellData['ru'][416690] = {name = "[q2]Руководство странника", additional_info = "Применение: 3.5 сек\nИнструменты: Набор виртуозного начертателя\nИнгредиенты:\nБронзовый слиток (30), Большой опал (2)\nНаходка:\nНекроситет\n\n[q2]Руководство странника\nСтановится персональным при надевании\nДвуручное Посох\nУрон: 4 - 6 Скорость 3.60\n(1.4 ед. урона в секунду)\n+16 к интеллекту\n+5 к выносливости\nПрочность: 85 / 85"}
