MultiLanguageSpellData['ru'][422277] = {name = "Пожирание сущности", additional_info = "Мгновенное действие\n[q]Пеплорон с силой бьет Углеколом по земле и начинает поглощать сущность игроков с клеймом, отбрасывая их.\n\n Игроки с эффектом \" Клеймо Углекола \" также высвобождают \" Живой жар \"."}
MultiLanguageSpellData['ru'][422280] = {name = "Злодейский смех", additional_info = "Мгновенное действие\n[q]Издает ужасающий смех, который продолжает звучать в головах противников. Оказавшись рядом друг с другом, цели получают 1623 ед. урона от темной магии и обращаются в бегство. Время действия – 6 сек."}
