MultiLanguageSpellData['ru'][425153] = {name = "Поджигатель", additional_info = "Мгновенное действие\n[q]Ваши атаки и способности ближнего боя с определенной вероятностью ставят на цель жестокое клеймо, наносящее [ 796 * (1.2^9)] ед. урона от огня за 6 сек. и дающее вам эффект \" Поджигатель \", суммирующийся до 15 раз. Урон увеличивается за каждый эффект вплоть до [ 796 * (1.2^5)].\n\n Когда у вас более 5 эффектов, эффект также наносит вам 50% своего урона. Когда вы накапливаете 15 эффектов, 10% наносимого цели урона также равномерно распределяется между другими ближайшими противниками. Эффект \" Поджигатель \" ослабевает раз в 3 сек. вне боя и снимается через 15 сек."}
MultiLanguageSpellData['ru'][425154] = {name = "Жестокое клеймо", additional_info = "Радиус действия: 15 м\nМгновенное действие\n[q]Ваши атаки и способности ближнего боя с определенной вероятностью ставят на цель жестокое клеймо, наносящее [ 796 * (1.2^9)] ед. урона от огня за 6 сек. и дающее вам эффект \" Поджигатель \", суммирующийся до 15 раз. Урон увеличивается за каждый эффект вплоть до [ 796 * (1.2^5)].\n\n Когда у вас более 5 эффектов, эффект также наносит вам 50% своего урона. Когда вы накапливаете 15 эффектов, 10% наносимого цели урона также равномерно распределяется между другими ближайшими противниками. Эффект \" Поджигатель \" ослабевает раз в 3 сек. вне боя и снимается через 15 сек."}
MultiLanguageSpellData['ru'][425156] = {name = "Лучащееся клеймо", additional_info = "Радиус действия: 15 м\nМгновенное действие\n[q]Ваши атаки и способности ближнего боя с определенной вероятностью ставят на цель жестокое клеймо, наносящее [ 796 * (1.2^9)] ед. урона от огня за 6 сек. и дающее вам эффект \" Поджигатель \", суммирующийся до 15 раз. Урон увеличивается за каждый эффект вплоть до [ 796 * (1.2^5)].\n\n Когда у вас более 5 эффектов, эффект также наносит вам 50% своего урона. Когда вы накапливаете 15 эффектов, 10% наносимого цели урона также равномерно распределяется между другими ближайшими противниками. Эффект \" Поджигатель \" ослабевает раз в 3 сек. вне боя и снимается через 15 сек."}
