MultiLanguageSpellData['ru'][426262] = {name = "Огненные грезы Лародара", additional_info = "Мгновенное действие\nСрабатывает приблизительно 1 раз(а) в минуту\n[q]Ваши исцеляющие эффекты с определенной вероятностью дают цели колючий барьер, поглощающий 1995 ед. урона и наносящий 240 ед. урона от сил природы атакующим противникам. Если барьер будет уничтожен, цель восполнит [ 582 * (3)] ед. здоровья за 6 сек. Если время действия барьера истечет до его уничтожения, универсальность цели будет повышена на 91 на 10 сек."}
