MultiLanguageSpellData['ru'][429532] = {name = "Атмосферные явления", additional_info = "[q]Страж\n \"Лунный луч\" или \"Ярость Элуны\" увеличивают урон, который получают от вас пораженные противники, на 6% на 6 сек.\n\nБаланс\n \"Полная луна\" или \"Ярость Элуны\" увеличивают урон, который получают от вас пораженные противники, на 6% на 6 сек."}
