MultiLanguageSpellData['ru'][429539] = {name = "Лунация", additional_info = "[q]Страж\n Способности тайной магии сокращают время восстановления \"Лунного луча\" на 3.0 сек.\n\nБаланс\n Способности тайной магии сокращают время восстановления \"Ярости Элуны\" на 2.0 сек., а время восстановления \"Новолуния\", \"Полумесяца\" и \"Полной луны\" – на 1.0 сек."}
