MultiLanguageSpellData['ru'][434276] = {name = "Высвобождение стихий", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Выпускает волны энергии стихий, наносящие пораженным противникам урон от магии льда."}
MultiLanguageSpellData['ru'][434277] = {name = "Удар копьем Ферин", additional_info = "Радиус действия: 250 м\n{Мгновенное действие} {Восстановление: 12 сек}\n[q]Дает Ферин сигнал атаковать, после чего она призывает в выбранной области Священное Пламя, наносящее противникам урон раз в 2 сек. в течение 30 сек."}
