MultiLanguageSpellData['ru'][435486] = {name = "Цареубийство", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Фантомы Пустоты скользят сквозь тени к выбранным целям, нанося игрокам на своем пути 4029421 ед. урона от темной магии."}
MultiLanguageSpellData['ru'][435487] = {name = "Сыворотка бесконечного удовольствия", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]Вы поглощаете сыворотку, усиливающую все ваши чувства на 3 сек. и уменьшающую получаемый вами урон на 100% до тех пор, пока эффект не предотвратит X ед. урона.\n Когда вы предотвращаете урон с помощью этого эффекта, вы совершаете контрудар, наносящий атакующему противнику Y ед. физического урона.\n\n В течение 1,5 сек. после активации эффекта вы вместо этого совершаете идеальный контрудар, наносящий на 100% больше урона.\n\n За одну активацию эффекта вы можете совершить только один контрудар или идеальный контрудар."}
MultiLanguageSpellData['ru'][435488] = {name = "Профанит проницательности", additional_info = "Мгновенное действие\n[q]Увеличивает максимальный запас маны на 1% за каждый уникальный цвет самоцветов Каз Алгара в вашем снаряжении."}
