MultiLanguageSpellData['ru'][436459] = {name = "Чародейское лезвие", additional_info = "[q]Ваши атаки расходуют часть прочности защищающего вас щита и наносят дополнительный урон от тайной магии в том же объеме. Время восстановления – 10 сек."}
MultiLanguageSpellData['ru'][436460] = {name = "Рвение", additional_info = "[q]Когда у вас более 80% здоровья, ваши атаки поглощают здоровье и наносят дополнительный урон от светлой магии, равный количеству поглощенного здоровья. Время восстановления – 1 сек."}
MultiLanguageSpellData['ru'][436461] = {name = "Знак самонадеянности", additional_info = "[q]Атакующие противники получают эффект \"Знак самонадеянности\", наносящий урон от темной магии раз в 2 сек. в течение 10 сек. и суммирующийся до 5 раз."}
MultiLanguageSpellData['ru'][436462] = {name = "Оппортунизм", additional_info = "[q]Повышает вероятность критического удара на 50% на 4 сек. после нанесения урона оглушенному противнику."}
MultiLanguageSpellData['ru'][436463] = {name = "Быстрый удар", additional_info = "[q]Ваши способности ближнего боя с вероятностью 100% позволяют совершить от 4 до 7 дополнительных автоатак. Время восстановления – 10 сек."}
MultiLanguageSpellData['ru'][436464] = {name = "Убийство", additional_info = "[q]Когда вы атакуете цель, у которой осталось менее 10% здоровья, вы пытаетесь добить ее и наносите урон от темной магии, равный 100% вашего максимального запаса здоровья.\n\n Этот эффект применяется к каждой цели только один раз."}
