MultiLanguageSpellData['ru'][438588] = {name = "Массовое извержение", additional_info = "Мгновенное действие\n[q]Усиленные заклинания позволяют следующему \"Извержению\" поразить до 3 целей. Поразив менее 3 целей, \"Извержение\" наносит на 15% больше урона за каждую недостающую цель."}
MultiLanguageSpellData['ru'][438590] = {name = "Твердый шаг", additional_info = "[q]Получаемый физический урон уменьшается на 2%.\n\n \"Разряд грома\" уменьшает получаемый вами урон на 8% на 5 сек.\n(Восстановление: 100мс)"}
MultiLanguageSpellData['ru'][438591] = {name = "Твердый шаг", additional_info = "Мгновенное действие\n[q]Получаемый физический урон уменьшается на 2%.\n\n \"Разряд грома\" уменьшает получаемый вами урон на 8% на 5 сек."}
MultiLanguageSpellData['ru'][438592] = {name = "Сыворотка бесконечного удовольствия", additional_info = "{Мгновенное действие} {Восстановление: 1 мин}\n[q]В начале каждой битвы вы систематически поглощаете небольшую дозу сыворотки, обостряющей все ваши чувства.\n Когда вы парируете атаку или уклоняетесь от нее под действием сыворотки, вы совершаете контрудар, наносящий атакующему противнику Y ед. физического урона."}
MultiLanguageSpellData['ru'][438593] = {name = "Пора перекусить", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Бенк Жужжикс призывает бочки вкусного меда, которые наносят игрокам в радиусе 3 м от мест приземления 12122247 ед. физического урона.\n\n Раз в 30 сек. на аромат меда прилетает хищная золопчела."}
MultiLanguageSpellData['ru'][438595] = {name = "Избыточный огонь", additional_info = "[q]Лед\n После того как вы применяете \"Кометную бурю\", следующее \"Ледяное копье\" вызывает \"Взрыв ледяного огня\", наносящий ближайшим противникам ([265.6% of Spell Power]) ед. урона от ледяного огня. Цели после 8-й получают уменьшенный урон.\n\n \"Взрыв ледяного огня\" с вероятностью 50% дает эффект \"Заморозка мозгов\".\n\nОгонь\n После того как вы применяете \"Метеорит\", следующий \"Огненный взрыв\" вызывает \"Взрыв ледяного огня\", наносящий ближайшим противникам ([265.6% of Spell Power]) ед. урона от ледяного огня. Цели после 8-й получают уменьшенный урон.\n\n \"Взрыв ледяного огня\" сокращает время восстановления \"Пламени феникса\" на 5 сек."}
MultiLanguageSpellData['ru'][438597] = {name = "Щит бури", additional_info = "[q]\"Вмешательство\" на 5 сек. дает цели щит, поглощающий магический урон в объеме 3-кратного показателя вашей брони."}
MultiLanguageSpellData['ru'][438598] = {name = "Щит бури", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]\"Вмешательство\" на 5 сек. дает цели щит, поглощающий магический урон в объеме 3-кратного показателя вашей брони."}
MultiLanguageSpellData['ru'][438599] = {name = "Кровопускающий выпад", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Вызывает у игрока кровотечение, наносящее 181834 ед. физического урона раз в 0.5 сек. в течение 3 сек. Эффект суммируется."}
MultiLanguageSpellData['ru'][438600] = {name = "Избыточный лед", additional_info = "[q]Огонь\n Когда вы поглощаете эффект \"Избыточный огонь\", ваше следующее заклинание \"Пламя феникса\" также применяет \"Кольцо обледенения\" с эффективностью 200%. При этом \"Кольцо обледенения\" не примораживает противников к месту.\n\n Когда вы поглощаете эффект \"Избыточный лед\", время восстановления \"Метеорита\" сокращается на 5 сек.\n\nЛед\n Когда вы поглощаете эффект \"Избыточный огонь\", ваше следующее заклинание \"Шквал\" также применяет \"Кольцо обледенения\" с эффективностью 150%. При этом \"Кольцо обледенения\" не примораживает противников к месту.\n\n Когда вы поглощаете эффект \"Избыточный лед\", время восстановления \"Кометной бури\" сокращается на 3 сек."}
MultiLanguageSpellData['ru'][438601] = {name = "Черная кровь", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]5 ед. урона от темной магии раз в 1 сек.\n\n Скорость передвижения снижена на 30 %."}
