MultiLanguageSpellData['ru'][440117] = {name = "Двойной росток", additional_info = "[q]После появления кровососущие лианы или цветы-симбионты с вероятностью 30% мгновенно выращивают такое же растение на ближайшей подходящей цели."}
MultiLanguageSpellData['ru'][440118] = {name = "Высадка", additional_info = "[q]Исцеление\n \"Быстрое восстановление\" и \"Буйный рост\" выращивают на цели цветок-симбионт на 6 сек.\n\nСила зверя\n Когда вы получаете или теряете эффект \"Тигриное неистовство\", ваша следующая способность ближнего боя, поражающая одну цель, выращивает на ней кровососущую лиану на 4 сек.\n\n(Восстановление: 200мс)"}
