MultiLanguageSpellData['ru'][440310] = {name = "Цепи гнета", additional_info = "Радиус действия: 300 м\nМгновенное действие\n[q]Оратор Крикс'визк сковывает всех игроков темными чарами. Если игрок находится дальше 10 м в течение 1 сек., Крикс'визк наносит ему 2424449 ед. урона от темной магии и притягивает обратно."}
