MultiLanguageSpellData['ru'][441321] = {name = "Безупречная техника", additional_info = "[q]Скрытность\n \"Незримый клинок\" и \"Тайный прием\" увеличивают урон завершающих приемов на 3% на 12 сек.\n\n Эффекты могут накладываться друг на друга.\n\nГоловорез\n \"Незримый клинок\" и \"Череда убийств\" увеличивают урон завершающих приемов на 3% на 12 сек.\n\n Эффекты могут накладываться друг на друга."}
MultiLanguageSpellData['ru'][441324] = {name = "Золотистый грифон из воспоминания", additional_info = "Применение: 1.5 сек\n[q]Позволяет призывать и отпускать золотистого грифона из воспоминания. Его свойства меняются в зависимости от навыка верховой езды и местонахождения.\n[q]\"В Штормграде любят львов, а грифон – почти что лев. Вот почему по всему Альянсу этих птиц часто используют для перелетов.\"\nТорговец:\nмнемомант Амуул\nЗона:\nДаларан\nЦена:\n25"}
MultiLanguageSpellData['ru'][441325] = {name = "Ветрокрыл из воспоминания", additional_info = "Применение: 1.5 сек\n[q]Позволяет призывать и отпускать зеленого ветрокрыла. Его свойства меняются в зависимости от навыка верховой езды и местонахождения.\n[q]\"Эти благородные создания участвовали в сотнях битв и помогли одержать сотни побед.\"\nТорговец:\nмнемомант Амуул\nЗона:\nДаларан\nЦена:\n25"}
