MultiLanguageSpellData['ru'][441841] = {name = "Звериная мощь", additional_info = "[q]Сила зверя\n \"Свирепый укус\" и \"Свирепое буйство\" наносят на 10% больше урона. \"Первобытный гнев\" наносит на 60% больше прямого урона.\n\nСтраж\n \"Трепка\" и \"Смести\" наносят на 20% больше урона."}
