MultiLanguageSpellData['ru'][442495] = {name = "Затмение", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Ки'веза укрывает части зала волнами тьмы, наносящими игрокам в области действия 8634473 ед. урона от темной магии."}
