MultiLanguageSpellData['ru'][442621] = {name = "Токсичные выделения", additional_info = "Радиус действия: 20 м\nМгновенное действие\n[q]Источает яд, покрывая им все свое тело. Пока яд действует, удары наносят урон от сил природы раз в 1 сек. и снижают скорость передвижения цели на 7% на 5 сек.\n\n Эффект суммируется."}
MultiLanguageSpellData['ru'][442624] = {name = "Метка разорителя", additional_info = "Дистанция ближнего боя\nМгновенное действие\n[q]Истребление\nПод действием \"Клинка разорителя\" способность \"Удар Хаоса\" применяет \"Метку разорителя\", увеличивающую получаемый целью урон на 7% на 20 сек. Суммируется до 2 раз.\n\n \"Метка разорителя\", примененная после \"Танца клинков\", применяется еще 1 раз.\n\nМесть\nПод действием \"Клинка разорителя\" способность применяет \"Метку разорителя\", увеличивающую получаемый целью урон на 7% на 20 сек. Суммируется до 2 раз.\n\n \"Метка разорителя\", примененная после \"Раскалывания душ\", применяется еще 1 раз.\n(Восстановление: 100мс)"}
