MultiLanguageSpellData['ru'][443442] = {name = "Гармония стихий", additional_info = "[q]Сокращает время восстановления \"Стража природы\" на 15 сек. и увеличивает объем восстанавливаемого здоровья еще на 10% вашего максимального запаса здоровья."}
