MultiLanguageSpellData['ru'][443527] = {name = "Резной воск Пламекона", additional_info = "Срабатывает приблизительно 2 раз(а) в минуту\n[q]Ваши заклинания с некоторой вероятностью наполняют воск энергией, превращая его в пылающую свечу на 15 сек. Свеча повышает вашу универсальность на 122 и еще на 32 , пока вы находитесь в освещенной области."}
