MultiLanguageSpellData['ru'][444665] = {name = "Узы души", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Вы связываете свою душу с душой союзника на 1 ч., в результате чего 20% получаемого им урона перенаправляется на вас как урон от темной магии. Эффект можно применить максимум к 5 союзникам:союзникам. Если вы применяете этот эффект к уже связанному с вами союзнику или отходите от него на 100 м, действие эффекта заканчивается."}
MultiLanguageSpellData['ru'][444666] = {name = "Узы души", additional_info = "[q]Вы связываете свою душу с душой союзника на 1 ч., в результате чего 20% получаемого им урона перенаправляется на вас как урон от темной магии. Эффект можно применить максимум к 5 союзникам:союзникам. Если вы применяете этот эффект к уже связанному с вами союзнику или отходите от него на 100 м, действие эффекта заканчивается."}
