MultiLanguageSpellData['ru'][449209] = {name = "Власть огненной решимости", additional_info = "Мгновенное действие\n[q]Араторские адаптации – Пожирающее пламя\n\n Применяет к оружию постоянные чары \"Власть огненной решимости\". Исцеляя союзников, вы с некоторой вероятностью пробуждаете эту власть и выпускаете волну теплого огня, восполняющую вам и 4 находящимся рядом союзникам 88776 ед. здоровья. Не действует на предметы ниже 350-го уровня."}
