MultiLanguageSpellData['ru'][449629] = {name = "Рвение одержимого", additional_info = "[q]Демонология\n Ваша демоническая душа наносит на 100% больше урона основной цели \"Руки Гул'дана\".\n\nКолдовство\n Ваша демоническая душа наносит на 100% больше урона целям, на которых действует ваше \"Нестабильное колдовство\"."}
MultiLanguageSpellData['ru'][449631] = {name = "Жестокая жатва", additional_info = "[q]Демонология\n Демоническая душа наносит на 10% больше урона.\n\n Когда вы поглощаете эффект \"Сердце демона\", вы даете энергию заключенной в вас демонической сущности, позволяя ей воплотиться и нанести цели [([240.402% of Spell Power]) * 0.4] ед. урона от темной магии.\n\nКолдовство\n Демоническая душа наносит на 10% больше урона.\n\n Когда вы поглощаете эффект \"Сумерки\", вы даете энергию заключенной в вас демонической сущности, позволяя ей воплотиться и нанести цели ([240.402% of Spell Power]) ед. урона от темной магии."}
