MultiLanguageSpellData['ru'][449634] = {name = "Упокоение", additional_info = "[q]Демонология\n \"Проклятие души\" наносит на 25% больше урона и делает это на 20% быстрее.\n\n Когда вы поглощаете эффект \"Сердце демона\", вы активируете \"Общую судьбу\" или \"Пиршество душ\".\n\nКолдовство\n \"Проклятие души\" наносит на 25% больше урона и делает это на 20% быстрее.\n\n Когда вы поглощаете эффект \"Сумерки\", вы активируете \"Общую судьбу\" или \"Пиршество душ\"."}
MultiLanguageSpellData['ru'][449637] = {name = "Воля Сатаэль", additional_info = "[q]Колдовство\n \"Порча\" наносит урон на 25% быстрее, а \"Блуждающий дух\" дает эффект \"Сумерки\".\n\nДемонология\n Дикие бесы наносят на 5% больше урона и с увеличенной на 5% вероятностью дают \"Сердце демона\" после взрыва."}
MultiLanguageSpellData['ru'][449638] = {name = "Тень смерти", additional_info = "[q]Колдовство\n Ваша демоническая сущность усиливает заклинание \"Гниение души\", отчего оно дает 3 осколка:осколков души с насыщенными душами.\n\nДемонология\n Ваша демоническая сущность усиливает заклинание \"Призыв демонического тирана\", отчего оно дает 3 осколка:осколков души с насыщенными душами."}
MultiLanguageSpellData['ru'][449639] = {name = "[q7]Наполнение воспоминаниями", additional_info = "Применение: 5 сек\nИнгредиенты:\nСущность Восточных королевств , Сущность Калимдора , Сущность Нордскола , Безжизненное каменное кольцо\n[q]Наполняет сущностями Азерот, чтобы вернуть утраченную силу."}
