MultiLanguageSpellData['ru'][449697] = {name = "Насыщенные клинки", additional_info = "Мгновенное действие\n[q]Атаки оружием в правой руке применяют к целям эффект \" Рана отравленным клинком \", наносящий 57563 ед. урона от сил природы раз в 0.5 сек. в течение 10 сек.\n\n Атаки оружием в левой руке применяют к целям эффект \" Рана клинком Бездны \", раз в 1.5 сек. наносящий 287816 ед. урона от темной магии союзникам в радиусе 4 в течение 9 сек."}
MultiLanguageSpellData['ru'][449698] = {name = "Рана отравленным клинком", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Атаки оружием в правой руке применяют к целям эффект \" Рана отравленным клинком \", наносящий 57563 ед. урона от сил природы раз в 0.5 сек. в течение 10 сек.\n\n Атаки оружием в левой руке применяют к целям эффект \" Рана клинком Бездны \", раз в 1.5 сек. наносящий 287816 ед. урона от темной магии союзникам в радиусе 4 в течение 9 сек."}
