MultiLanguageSpellData['ru'][449700] = {name = "Искажение гравитации", additional_info = "Радиус действия: 40 м\n{Мгновенное действие} {Восстановление: 40 сек}\n[q]Щелкнув пальцами, вы искажаете гравитацию вокруг цели и 4 ближайших противников:ближайших противников, подвешивая их в воздухе на 3 сек.\n Когда цели падают на землю, ближайшие противники получают ([50% of Spell Power]) ед. урона от тайной магии."}
MultiLanguageSpellData['ru'][449701] = {name = "Связанная кровью стойкость", additional_info = "[q]При поглощении камня здоровья вы всегда получаете бонус \"Горящей души\": исцеление от камня здоровья усиливается на 30%, а ваш максимальный запас здоровья увеличивается на 20% на 12 сек."}
MultiLanguageSpellData['ru'][449702] = {name = "Сочащийся мед", additional_info = "Направляемое (Применение: 20 сек)\n[q]Когда хмельной выброс уничтожают, из него вытекает лужа горячего меда, наносящая игрокам в области действия 2909339 ед. урона от огня раз в 1.5 сек. и снижающая скорость передвижения на 50%.\n\n Лужа постепенно уменьшается в размерах."}
MultiLanguageSpellData['ru'][449703] = {name = "Друзья во тьме", additional_info = "[q]Прочность щита от \"Темного пакта\" увеличивается еще на 50% пожертвованного здоровья."}
MultiLanguageSpellData['ru'][449704] = {name = "Общая судьба", additional_info = "[q]Убивая противника, вы направляете его истерзанную душу в другого находящегося рядом противника на 3 сек. Этот эффект наносит целям в радиусе 10 м ([50.6531% of Spell Power]) ед. урона от темной магии раз в 1 сек.\n\n Цели после 8-й получают уменьшенный урон."}
