MultiLanguageSpellData['ru'][449885] = {name = "Кровавый крюк глубинного охотника", additional_info = "Радиус действия: 50 м\nМгновенное действие\n[q]Атаки ближнего боя могут вонзить в цель кровавый крюк. Через 4 сек. крюк притягивается обратно и рвет плоть цели, нанося ( 1 * 836 ) ед. физического урона.\n\n Пока цель на крюке, получаемые ею критические физические удары забивают крюк еще глубже, нанося ( 1 * 118 ) ед. дополнительного физического урона за 8 сек."}
MultiLanguageSpellData['ru'][449886] = {name = "Кровавый крюк глубинного охотника", additional_info = "Радиус действия: 50 м\nМгновенное действие\n[q]Атаки ближнего боя могут вонзить в цель кровавый крюк. Через 4 сек. крюк притягивается обратно и рвет плоть цели, нанося ( 1 * 836 ) ед. физического урона.\n\n Пока цель на крюке, получаемые ею критические физические удары забивают крюк еще глубже, нанося ( 1 * 118 ) ед. дополнительного физического урона за 8 сек."}
