MultiLanguageSpellData['ru'][449888] = {name = "Обстрел ядом", additional_info = "Радиус действия: 40 м\nМгновенное действие\n[q]Выпускает в цель ядовитый снаряд, наносящий урон от сил природы и отравляющий противника, нанося дополнительный урон от сил природы раз в 1 сек. в течение 5 сек."}
MultiLanguageSpellData['ru'][449889] = {name = "Обстрел ядом", additional_info = "Радиус действия: 40 м\nПрименение: 3 сек\n[q]Выстреливает в цель несколькими отравленными зарядами. Каждый из них наносит мгновенный урон от сил природы и периодический урон от сил природы в течение 5 сек."}
