MultiLanguageSpellData['ru'][449892] = {name = "Нерубский дротик с отравленным острием", additional_info = "Радиус действия: 50 м\nМгновенное действие\n[q]Атаки дальнего боя могут впрыснуть цели парализующий яд, наносящий ( 1 * 592 ) ед. урона от сил природы за 9 сек.\n\n За каждую секунду, что цель двигается, ваша скорость повышается на ( 24 / 5) на 10 сек. Суммируется до 5 раз."}
