MultiLanguageSpellData['ru'][450379] = {name = "Живительный импульс", additional_info = "[q]Когда \"Часовой\" наносит урон, вы с вероятностью 15% получаете 5 ед. концентрации.\n\n Вероятность снижается за каждую дополнительную цель под действием коллапсирующих эффектов \"Часовой\"."}
