MultiLanguageSpellData['ru'][450381] = {name = "С закрытыми глазами", additional_info = "[q]Стрельба\n В течение 8 сек. после активации \"Меткого выстрела\" все способности гарантированно применяют к целям эффект \"Часовой\".\n\nВыживание\n В течение 8 сек. после активации \"Согласованной атаки\" все способности гарантированно применяют к целям эффект \"Часовой\"."}
