MultiLanguageSpellData['ru'][450763] = {name = "Аспект гармонии", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Ткач туманов\nВы сохраняете запас жизненной силы в объеме 10% наносимого урона и 30% вашего исцеления. Избыточное исцеление дает уменьшенное количество жизненной силы.\n\n В течение 10 сек. после применения \"Громового чая\" ваши заклинания и способности поглощают сохраненный запас жизненной силы и восполняют 40% дополнительного здоровья за 8 сек.\n\nХмелевар\nВы сохраняете запас жизненной силы в объеме 15% наносимого урона и 7% вашего эффективного исцеления.\n\n В течение 10 сек. после применения \"Божественного отвара\" ваши заклинания и способности поглощают сохраненный запас жизненной силы и наносят 40% дополнительного урона за 8 сек."}
