MultiLanguageSpellData['ru'][450986] = {name = "Вопреки всему", additional_info = "[q]\"Стремительные удары\" повышают вашу ловкость на 1% на 5 сек. Эффект суммируется до 20 раз."}
MultiLanguageSpellData['ru'][450987] = {name = "Опытный взгляд", additional_info = "[q]Когда вы поражаете одну и ту же цель 5 раза:раз за 2 сек., ваша скорость повышается на 1%. Эффект суммируется до 10 раз."}
MultiLanguageSpellData['ru'][450988] = {name = "В одиночку против армии", additional_info = "[q]Урон от \"Неистовых кулаков\" и \"Удара бочонком\" засчитывается для накапливания \"Стремительных зарядов\" в удвоенном объеме.\n\n Урон от \"Неистовых кулаков\" увеличивается на 20%.\n Урон от \"Удара бочонком\" увеличивается на 35%."}
MultiLanguageSpellData['ru'][450989] = {name = "Тренировка эффективности", additional_info = "[q]Хмелевар\n Способности, расходующие энергию, наносят на 20% больше урона.\n За каждые 50 ед. потраченной энергии время восстановления \"Оружия ордена\" сокращается на 1 сек.\n\nТанцующий с ветром\n Способности, расходующие энергию, наносят на 40% больше урона.\n За каждые 50 ед. потраченной энергии время восстановления \"Бури, земли и огня\" сокращается на 1 сек."}
