MultiLanguageSpellData['ru'][451180] = {name = "С закрытыми глазами", additional_info = "Мгновенное действие\n[q]В течение 8 сек. после активации [ Стрельба : \"Меткого выстрела\" /\n\nВыживание\n\"Согласованной атаки\" ] все способности гарантированно применяют к целям эффект \"Часовой\"."}
MultiLanguageSpellData['ru'][451181] = {name = "Убежденная целеустремленность", additional_info = "Мгновенное действие\n[q]Хмелевар\nКогда вы применяете \"Очищающий отвар\", вы накапливаете [(Сила заклинаний * 100 / 100) * (1 + Универсальность)] ед. жизненной силы. Этот объем увеличивается в зависимости от уровня \"Пошатывания\".\n\nТкач туманов\nКогда вы применяете способность \"Оживить\", вы накапливаете [(Сила заклинаний * 100 / 100) * (1 + Универсальность)] ед. жизненной силы. Этот объем увеличивается в зависимости от количества недавних срабатываний \"Туманного потока\"."}
