MultiLanguageSpellData['ru'][451199] = {name = "Отчет мастера шпионажа", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Атакующие заклинания отправляют к врагам паука-шпиона, повышающего ваш интеллект на 1 за каждый отчет разведки. Суммируется до 40 раз. Эффект срабатывает не чаще раза в 6 сек."}
