MultiLanguageSpellData['ru'][451211] = {name = "Звездный проводник", additional_info = "[q]Баланс, Сила зверя, Страж, Исцеление\n Урон от \"Гнева\", \"Звездного потока\" и \"Звездного огня\" увеличивается на 5%.\n\n Время восстановления \"Звездного потока\" сокращается на 4 сек., а затраты маны на его применение уменьшаются на 50%."}
