MultiLanguageSpellData['ru'][451233] = {name = "Бдительный дозор", additional_info = "Мгновенное действие\n[q]Критический урон от \"Нокаутирующего удара\" увеличивается на 20%. Кроме того, \"Нокаутирующий удар\" увеличивает урон от следующей серии \"Стремительных ударов\" на 10%."}
MultiLanguageSpellData['ru'][451234] = {name = "Призрак Бездны", additional_info = "[q]Превращает ваше исчадие Тьмы или подчинителя разума в призрака Бездны.\n\nПризрак Бездны\nНа 15 сек. призывает призрака Бездны, применяющего \"Пытку Бездной\" на расстоянии. Чем выше уровень здоровья цели, тем больше урона наносит \"Пытка Бездной\". Максимальная прибавка при полном запасе здоровья – 50%. [ Тьма : Когда призрак Бездны наносит урон, вы получаете 2 ед. безумия. /\n\nПослушание, Свет\nКогда призрак Бездны наносит урон, вы восполняете 0.5% запаса маны. ]"}
MultiLanguageSpellData['ru'][451235] = {name = "Призрак Бездны", additional_info = "Радиус действия: 40 м\n{Мгновенное действие} {Восстановление: 3 мин}\n[q]На 15 сек. призывает призрака Бездны, применяющего \"Пытку Бездной\" на расстоянии. Чем выше уровень здоровья цели, тем больше урона наносит \"Пытка Бездной\". Максимальная прибавка при полном запасе здоровья – 50%. [ Тьма : Когда призрак Бездны наносит урон, вы получаете 2 ед. безумия. /\n\nПослушание, Свет\nКогда призрак Бездны наносит урон, вы восполняете 0.5% запаса маны. ]"}
