MultiLanguageSpellData['ru'][451754] = {name = "Упорядоченные стихии", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Пока действует \"Буря, земля и огонь\", затраты энергии ци на применение способностей сокращаются на 1 ед., а \"Нокаутирующий удар\" сокращает время восстановления соответствующих способностей еще на 1 сек.\n\n При активации \"Буря, земля и огонь\" мгновенно восстанавливает \"Удар восходящего солнца\" и дает 2 ед. энергии ци."}
MultiLanguageSpellData['ru'][451755] = {name = "Область взрыва", additional_info = "[q]\"Горящий фитиль\" теперь применяет \"Живую бомбу\" максимум к 3 целям:целям.\n\n \"Живая бомба\" теперь распространяется на 5 противников:противников."}
MultiLanguageSpellData['ru'][451757] = {name = "Сотворение кратеров", additional_info = "[q]\"Возгорание\" дает вам эффект \"Горящий фитиль\" и увеличивает урон от \"Живой бомбы\" на 30%.\n\nОгонь\n[q]Your chance of gaining Lit Fuse is increased by 15% while under the effects of Combustion."}
