MultiLanguageSpellData['ru'][451760] = {name = "Взрывная изобретательность", additional_info = "[q]Вероятность получения \"Горящего фитиля\" при поглощении \"Полосы везения\" повышается на 4%.\n\n Урон от \"Живой бомбы\" увеличивается на 50%."}
