MultiLanguageSpellData['ru'][453250] = {name = "Кристаллизация", additional_info = "Мгновенное действие\n[q]Повышает основную характеристику (Основная характеристика) на 733 на 1 ч. Усиливающая руна."}
MultiLanguageSpellData['ru'][453251] = {name = "Живая бомба", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Цель становится живой бомбой и получает 4 ед. урона от огня за 2 сек. Затем она взрывается, нанося ([26.8% of Spell Power]) ед. урона от огня себе и уменьшенный урон противникам в радиусе 10 м.\n\n Другие противники, пораженные взрывом, также становятся живыми бомбами, но дальше эффект не распространяется."}
