MultiLanguageSpellData['ru'][454391] = {name = "Безграничная мощь", additional_info = "[q]Стихии\n Когда вы расходуете энергию Водоворота, ваша скорость повышается на 1% на 15 сек.\n\n Эффекты могут накладываться друг на друга.\n\nСовершенствование\n Когда вы расходуете эффекты \"Оружия Водоворота\", ваша скорость повышается на 1% на 15 сек.\n\n Эффекты могут накладываться друг на друга."}
