MultiLanguageSpellData['ru'][454438] = {name = "Азеритовый заряд", additional_info = "Радиус действия: 100 м\nПрименение: 3 сек\n[q]Совершает рывок к цели и вызывает взрыв энергии азерита, наносящий противникам в радиусе 8 м 4134 ед. урона от тайной магии мгновенно и еще 1102 ед. урона от тайной магии раз в 1 сек. в течение 5 сек."}
