MultiLanguageSpellData['ru'][457052] = {name = "Метка ловчего смерти", additional_info = "[q]Ликвидация\n \"Внезапный удар\", примененный в состоянии незаметности, применяет к цели 3 эффекта:эффектов \"Метка ловчего смерти\". Когда вы расходуете как минимум 5 приема:приемов серии на атаки против отмеченной цели, вы поглощаете один эффект \"Метка ловчего смерти\" и наносите ([120% of Attack Power]) ед. урона от чумы, а также увеличиваете урон от следующей способности \"Внезапный удар\" или \"Расправа\" на 50%.\n Вы можете отметить только одну цель единовременно.\n\nСкрытность\n \"Удар Тьмы\", примененный в состоянии незаметности или под действием \"Танца теней\", применяет к цели 3 эффекта:эффектов \"Метка ловчего смерти\". Когда вы расходуете как минимум 5 приема:приемов серии на атаки против отмеченной цели, вы поглощаете один эффект \"Метка ловчего смерти\" и наносите ([120% of Attack Power]) ед. урона от чумы, а также увеличиваете урон от следующей способности на 50%.\n Вы можете отметить только одну цель единовременно."}
MultiLanguageSpellData['ru'][457053] = {name = "Устранение свидетелей", additional_info = "[q]Ликвидация\n После того как вы применяете \"Метку ловчего смерти\", следующий \"Веер клинков\" наносит ([100% of Attack Power]) ед. дополнительного урона от чумы и продлевает серию приемов еще на 1.\n\nСкрытность\n После того как вы применяете \"Метку ловчего смерти\", следующий \"Шквал сюрикэнов\" наносит ([100% of Attack Power]) ед. дополнительного урона от чумы и продлевает серию приемов еще на 1."}
MultiLanguageSpellData['ru'][457054] = {name = "Убить их всех", additional_info = "[q]Автоатаки наносят отмеченным целям ([25% of Attack Power]) ед. дополнительного урона от чумы."}
MultiLanguageSpellData['ru'][457055] = {name = "Исключительная концентрация", additional_info = "[q]Когда вы наносите урон цели, на которую не действует ваша метка, отмеченная вами цель получает 5% урона от чумы."}
MultiLanguageSpellData['ru'][457056] = {name = "Остаточная тьма", additional_info = "[q]Ликвидация\n По окончании времени действия \"Знака смерти\" наносимый вами урон от сил природы увеличивается на 30% на 30 сек.\n\nСкрытность\n По окончании времени действия \"Теневых клинков\" наносимый вами урон от темной магии увеличивается на 30% на 30 сек."}
MultiLanguageSpellData['ru'][457057] = {name = "Темная поступь", additional_info = "[q]За каждый поглощенный эффект \"Метка ловчего смерти\" время восстановления \"Шага сквозь тень\" сокращается на 3 сек."}
MultiLanguageSpellData['ru'][457058] = {name = "Непроглядная ночь", additional_info = "[q]Ликвидация\n Когда вы поглощаете последнюю \"Метку ловчего смерти\" на цели или ваша цель погибает, вы восполняете 40 ед. энергии, а ваше следующее \"Отравление\", расходующее серию приемов максимальной длины, гарантированно наносит критический удар, наносит на 60% больше урона и применяет 3 эффекта:эффектов \"Метка ловчего смерти\".\n\nСкрытность\n Когда вы поглощаете последнюю \"Метку ловчего смерти\" на цели или ваша цель погибает, вы восполняете 40 ед. энергии, а ваше следующее \"Потрошение\", расходующее серию приемов максимальной длины, гарантированно наносит критический удар, наносит на 60% больше урона и применяет 3 эффекта:эффектов \"Метка ловчего смерти\"."}
MultiLanguageSpellData['ru'][457059] = {name = "Flame Rift [NYI]", additional_info = "[q]\"Пространственный разлом\" теперь может призвать мощный \"Пламенный разлом\"."}
MultiLanguageSpellData['ru'][457060] = {name = "Lessons of Space-Time [NYI]", additional_info = "[q]Пока существует открытый вами пространственный разлом, наносимый вами урон увеличивается на 0%."}
MultiLanguageSpellData['ru'][457062] = {name = "Символическая победа", additional_info = "[q]Ликвидация\n Способность \"Отравляющий укол\" также увеличивает урон от следующего \"Отравления\" на 18%.\n\nСкрытность\n Способность \"Символы смерти\" также увеличивает урон от следующего \"Потрошения\" или \"Черного пороха\" на 18%."}
