MultiLanguageSpellData['ru'][459922] = {name = "Неудержимая первобытная ярость", additional_info = "[q]\"Согласованная атака\" усиливает вас и вашего питомца первобытной мощью. Пока она действует, \"Команда \"Взять!\" дает еще 2 эффекта:эффектов \"Наконечника копья\", ваша скорость повышается на 10%, а бонус к урону от \"Наконечника копья\" – на 50%."}
