MultiLanguageSpellData['ru'][460444] = {name = "Азартный игрок!", additional_info = "Мгновенное действие\n[q]Герои становятся азартными игроками. Наносимый урон и сила исцеления увеличиваются на 10%, а скорость передвижения повышается на 30% на 15 сек."}
MultiLanguageSpellData['ru'][460448] = {name = "Нечестивая порча", additional_info = "[q]\"Темное превращение\" на 6 сек. окружает вашего вурдалака роем злобных насекомых, которые жалят находящихся рядом противников, поражая их \"Смертоносной чумой\" и заражая нечестивой болезнью, наносящей ([27.832% of Attack Power]) ед. урона за 14 сек. Суммируется до 4 раз."}
