MultiLanguageSpellData['ru'][460454] = {name = "Электрическое обслуживание", additional_info = "Мгновенное действие\n[q]Большая МАМА заряжает энергией находящиеся рядом уничтоженные дроны, расходуя 20) ед. энергии на каждого дрона и возвращая их в рабочее состояние. При этом вылетают электрические искры, наносящие пораженным игрокам 10 ед. урона от сил природы."}
