MultiLanguageSpellData['ru'][462269] = {name = "Перенос кислотного снаряда", additional_info = "Мгновенное действие\n[q]Несет \" Кислотный снаряд \".\n\nКислотный снаряд :\nВыпускает кислотный снаряд, наносящий противникам в радиусе 10 м 3454209 ед. урона от сил природы и создающий лужу кислоты, которая наносит 287549 ед. урона от сил природы раз в 1 сек. в течение 12 сек ."}
MultiLanguageSpellData['ru'][462270] = {name = "Перенос снаряда ледяной шрапнели", additional_info = "Мгновенное действие\n[q]Несет \" Снаряд ледяной шрапнели \".\n\nСнаряд ледяной шрапнели :\nВыпускает снаряд, разлетающийся на ледяные осколки, которые наносят противникам в радиусе 8 м 2875492 ед. урона от магии льда. Наносит на 400% больше урона летающим существам."}
